828: static bool ggml_backend_cuda_buffer_cpy_tensor(ggml_backend_buffer_t buffer, const ggml_tensor * src, ggml_tensor * dst) {
829:     if (ggml_backend_buffer_is_cuda(src->buffer)) {
830:         ggml_backend_cuda_buffer_context * src_ctx = (ggml_backend_cuda_buffer_context *)src->buffer->context;
831:         ggml_backend_cuda_buffer_context * dst_ctx = (ggml_backend_cuda_buffer_context *)dst->buffer->context;
832:         // compare the backing physical devices: distinct virtual devices may share one physical GPU,
833:         // in which case a same-device copy (not a peer copy) is required
834:         const int src_physical = ggml_cuda_get_physical_device(src_ctx->device);
835:         const int dst_physical = ggml_cuda_get_physical_device(dst_ctx->device);
836:         if (src_physical == dst_physical) {
837:             CUDA_CHECK(cudaMemcpyAsync(dst->data, src->data, ggml_nbytes(src), cudaMemcpyDeviceToDevice, cudaStreamPerThread));
838:         } else {
839: #ifdef GGML_CUDA_NO_PEER_COPY
840:             return false;
841: #else
842:             CUDA_CHECK(cudaMemcpyPeerAsync(dst->data, dst_physical, src->data, src_physical, ggml_nbytes(src), cudaStreamPerThread));
843: #endif
844:         }
845:         CUDA_CHECK(cudaStreamSynchronize(cudaStreamPerThread));
846:         return true;
847:     }
